export function lineTotal(priceCents, qty) {
  return priceCents * qty;
}

files.src/cart.js:
import { lineTotal } from "./money.js";

export function cartTotal(lines) {
  return lines.reduce((sum, line) => sum + lineTotal(line.priceCents, line.qty), 0);
}
